{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "어린이공원에서 맥주 한 캔을 마신 경우 과태료가 무조건 부과되는지 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "어린이공원이라고 해서 무조건 과태료가 나오는 것은 아니다. 서울특별시 도시공원 조례 제22조의3에 따르면 시장은 어린이공원을 금주구역으로 지정할 수 있으므로, 해당 공원이 금주구역으로 지정되었는지 여부에 따라 달라진다. 금주구역으로 지정된 어린이공원에서 음주를 한 경우 조례 제23조제4항에 따라 10만원의 과태료가 부과되며, 제23조제2항에 따라 위반 정도·횟수·동기·결과 등을 고려하여 과태료 금액의 2분의 1 범위에서 감경 또는 가중될 수 있다.",
          "b_ids": "도시공원:제22조의3, 도시공원:제23조제4항, 도시공원:제23조제2항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
